import {rand,shapeTypes} from '../logic.js';import {gameFrame,roundFlow,shape} from '../ui.js';
export function mountGame(root,c){const flow=roundFlow(root,c),n=c.difficulty==='easy'?1:c.difficulty==='hard'?3:2,history=[];function next(){flow.next();const index=history.length;const value=index>=n&&Math.random()<.45?history[index-n]:shapeTypes[rand(shapeTypes.length)];const reference=history[index-n];history.push(value);const area=gameFrame(root,index<n?'Build your memory':`Match ${n} ${n===1?'step':'steps'} back?`,index<n?`Remember this symbol. ${index+1} of ${n} warm-up items.`:`Compare with the symbol shown ${n} ${n===1?'item':'items'} earlier.`);area.innerHTML=`<div class="memory-symbol">${shape(value,'#7660c8',110)}</div>${index<n?'<p class="subtle">Watch and remember…</p>':'<div class="choice-row"><button id="no">Different</button><button class="primary" id="yes">Match</button></div>'}`;if(index<n)c.session.schedule(next,c.mode==='learn'?1800:1200);else for(const [id,guess] of [['no',false],['yes',true]])area.querySelector('#'+id).onclick=()=>flow.answer((value===reference)===guess,`The symbol ${n} back was a ${reference}; this is a ${value}.`,next,{nBack:n});}next();return {dispose(){}};}
